// Validate timeline update request
const body = $input.item.json.body;

if (!body.thread_id || !body.org_id) {
  throw new Error('Missing required fields: thread_id, org_id');
}

return {
  json: {
    thread_id: body.thread_id,
    org_id: body.org_id,
    event_type: body.event_type || 'manual_update',
    file_id: body.file_id || null,
    message_id: body.message_id || null,
    forced: body.forced || false
  }
};

// Build context for checklist evaluation
const threadData = $('Load Thread Info').item.json;
const files = $('Load All Files').all().map(item => item.json);
const inData = $('Load Current IN').item.json;

// Group files by category
const filesByCategory = {};
for (const file of files) {
  const category = file.category || 'Outros';
  if (!filesByCategory[category]) {
    filesByCategory[category] = [];
  }
  filesByCategory[category].push(file);
}

// Define expected categories based on typical environmental process
const expectedCategories = [
  'Documentos do Empreendedor',
  'Projetos Arquitetônicos',
  'Comprovantes/Boletos',
  'Licenças Anteriores'
];

const context = {
  thread_id: $('Validate Input').item.json.thread_id,
  org_id: $('Validate Input').item.json.org_id,
  thread_title: threadData.title,
  municipality: threadData.municipality,
  state: threadData.state,
  files_by_category: filesByCategory,
  total_files: files.length,
  expected_categories: expectedCategories,
  in_number: inData?.instruction_number || 'N/A',
  in_version: inData?.version || 'N/A'
};

return { json: context };

// Evaluate checklist and determine stage
const ctx = $input.item.json;

const checklist = [];
const stages = [
  { name: 'Coleta de documentos', status: 'in_progress', progress: 0 },
  { name: 'Conferência interna', status: 'pending', progress: 0 },
  { name: 'Pronto para protocolo', status: 'pending', progress: 0 },
  { name: 'Aguardando parecer', status: 'pending', progress: 0 }
];

// Check each expected category
for (const category of ctx.expected_categories) {
  const hasFiles = ctx.files_by_category[category] && ctx.files_by_category[category].length > 0;
  checklist.push({
    item: category,
    status: hasFiles ? 'completed' : 'pending',
    files_count: ctx.files_by_category[category]?.length || 0
  });
}

// Calculate overall progress
const completedItems = checklist.filter(item => item.status === 'completed').length;
const totalItems = checklist.length;
const progressPercent = Math.round((completedItems / totalItems) * 100);

// Update stage status based on progress
if (progressPercent >= 100) {
  stages[0].status = 'completed';
  stages[0].progress = 100;
  stages[1].status = 'in_progress';
  stages[1].progress = 50;
} else if (progressPercent >= 50) {
  stages[0].status = 'in_progress';
  stages[0].progress = progressPercent;
} else {
  stages[0].status = 'in_progress';
  stages[0].progress = progressPercent;
}

return {
  json: {
    ...ctx,
    checklist: checklist,
    stages: stages,
    overall_progress: progressPercent,
    ready_for_submission: progressPercent >= 100
  }
};

// Determine what changed since last event
const currentData = $('Evaluate Checklist').item.json;
const lastEvent = $input.item.json;

let hasChanges = true;
let changeDescription = 'Timeline atualizada';

if (!lastEvent || lastEvent.length === 0) {
  changeDescription = 'Timeline inicial criada';
} else {
  const last = Array.isArray(lastEvent) ? lastEvent[0] : lastEvent;
  // In production: compare last event status with current to detect real changes
  changeDescription = `Progresso atualizado para ${currentData.overall_progress}%`;
}

return {
  json: {
    ...currentData,
    has_changes: hasChanges,
    change_description: changeDescription
  }
};

// Prepare timeline events for insertion
const data = $input.item.json;
const events = [];

// Create event for each stage
for (const stage of data.stages) {
  events.push({
    thread_id: data.thread_id,
    event_type: 'stage_update',
    title: stage.name,
    description: `Status: ${stage.status}, Progresso: ${stage.progress}%`,
    status: stage.status,
    event_metadata: JSON.stringify({
      progress: stage.progress,
      checklist_items: data.checklist.length,
      overall_progress: data.overall_progress
    })
  });
}

return events.map(event => ({ json: event }));

// Build response with updated timeline
const data = $('Detect Changes').item.json;

return {
  json: {
    status: 'success',
    thread_id: data.thread_id,
    overall_progress: data.overall_progress,
    checklist: data.checklist,
    stages: data.stages,
    ready_for_submission: data.ready_for_submission,
    change_description: data.change_description,
    message: 'Timeline atualizada com sucesso'
  }
};

// No changes detected
const data = $input.item.json;

return {
  json: {
    status: 'no_changes',
    thread_id: data.thread_id,
    message: 'Nenhuma mudança detectada na timeline'
  }
};
